  "codebook": {
    "definition": "Credit-claiming is defined as a political communication strategy in which a member of Congress attempts to generate the belief among constituents (or a broader audience) that they are personally responsible for causing the government to execute a specific, desirable action or deliver a tangible benefit.",
    "clarification": "To classify a press release as credit-claiming (1), the senator must explicitly or implicitly assert that their individual effort, co-sponsorship, committee work, or legislative authorship was a cause of a positive federal outcome. Positive outcomes include the allocation of federal grants, project funding, disaster designations, the passage of a specific senator-backed bill or amendment, or successful interventions with federal agencies that benefit the senator's state or the nation.",
    "positive_examples": [
      {
        "document_id": "1862",
        "explanation": "Senators Baucus and Tester explicitly claim credit for 'delivering on their promise' to secure $12.5 million in federal funding for local military projects in Butte, Montana."
      },
      {
        "document_id": "2697",
        "explanation": "Senator Inouye claims credit for personally finding an alternative federal funding source of $225,000 to manage invasive coqui frogs on the Big Island after a previous request was denied."
      }
    ],
    "negative_clarification": "Do not classify a text as credit-claiming (0) if the senator is merely stating a policy position, criticizing opponents, introducing a bill that has not yet passed, or writing a letter asking an agency to act. These activities represent 'position-taking' or 'advertising' rather than claiming responsibility for a completed government action. Similarly, general commentary, memorial tributes, and committee oversight actions that do not claim credit for a successful outcome are classified as 0.",
    "negative_examples": [
      {
        "document_id": "656",
        "explanation": "Senator Kerry's statement is purely a policy critique targeting the Bush Administration's record on port security. He does not claim credit for any positive action or resource allocation."
      },
